function entities(q){const n=norm(q),o={};const d=n.match(/\biphone\s*(\d{1,2})(?:\s*(pro|max|mini|plus))?\b/);if(d)o.device=`iPhone ${d[1]}${d[2]?' '+d[2][0].toUpperCase()+d[2].slice(1):''}`;const r=n.match(/\b(3|4|6|8|12|16)\s*gb\b/);if(r)o.memory=`${r[1]} GB`;return o;}
function isFollowUp(q){const n=norm(q);return raw(n).length<=8&&(/^(and|what about|how about|why|how|where|when|can it|does it|is it|that|it|then|so)\b/.test(n)||/\b(it|that|this one|same thing|those settings)\b/.test(n));}
function context(q){if(!isFollowUp(q)||!state.lastQuestion)return q;return `${state.lastQuestion} ${q} ${state.lastTopic} ${Object.values(state.entities).join(' ')}`;}

const GTA_STRONG=/\b(gta\s*v|grand\s*theft\s*auto|rockstar|los\s*santos|blaine\s*county|franklin|michael|trevor|lamar|lester|chop|amanda|jimmy|tracey|dave\s*norton|steve\s*haines|devin\s*weston|heist|heists|prologue|deathwish|big\s*score|paleto|merryweather|fib|IAA|fort\s*zancudo|mount\s*chiliad|sandy\s*shores|vespucci|vinewood|wanted\s*level|story\s*mode|gta\s*online|special\s*ability|los\s*santos\s*customs)\b/i;
const PROJECT_STRONG=/\b(gta\s*v\s*ios|ios\s*project|ios\s*launcher|launcher|dxmt|metalfx|lowmem|memrestrict|sideload|ipa|signing|signed\s*app|compatibility\s*checker|iphone|ipad|macos|a1[2-9]|m[1-9]\s*chip|xinput)\b/i;
