const OFF_TOPIC_HINTS=/\b(weather|cuaca|politic|politics|president|presiden|football|soccer|basketball|recipe|resep|homework|matematika|math|history\s+of\s+indonesia|coding\s+javascript|python\s+code|relationship|pacar|dating|medical|medicine|crypto|bitcoin|stock\s+price|news\s+today|anime|movie\s+recommendation)\b/i;
function greeting(q){const n=norm(q);if(/^(yo|hey|hi|hello|hallo|halo|hai|sup|wassup)(\s+franklin)?$/.test(n)||/^(yo|hey)\s+f$/.test(n))return{text:"Yo, what's good, homie? Franklin here. Ask me about GTA V or the GTA V iOS Project and I'll help if I know it.",topic:'small-talk'};if(/^(thanks|thank you|thx|makasih|terima kasih)$/.test(n))return{text:"You got it, homie. Hit me up if you need anything about GTA V or the iOS project.",topic:'small-talk'};if(/^(bye|goodbye|see ya|later|dadah)$/.test(n))return{text:"Aight, catch you later. If GTA V or the iOS project gives you trouble, you know where to find me.",topic:'small-talk'};return null;}
function domainDecision(q){const n=norm(q);if(!n)return{allowed:false,reason:'empty'};if(GTA_STRONG.test(n)||PROJECT_STRONG.test(n))return{allowed:true,reason:'strong'};if(state.lastTopic&&state.lastTopic!=='unknown'&&state.lastTopic!=='off-topic'&&isFollowUp(q))return{allowed:true,reason:'context'};if(OFF_TOPIC_HINTS.test(n))return{allowed:false,reason:'off-topic'};const list=raw(n),weak=list.filter(t=>PROJECT_WEAK.includes(t));const e=entities(q);if(weak.length>=2)return{allowed:true,reason:'project-signals'};if(weak.length>=1&&(e.device||e.memory))return{allowed:true,reason:'device-context'};if(/\b(3|4|6|8|12|16)\s*gb\b/.test(n)&&/\b(settings?|fps|ram|memory|graphics|resolution)\b/.test(n))return{allowed:true,reason:'memory-context'};return{allowed:false,reason:'no-domain-signal'};}
function offTopic(){return{text:"Aight, that's outside my lane, homie. I'm only here to help with GTA V and the GTA V iOS Project. Ask me about the game, characters, missions, settings, installation, compatibility, performance, or the launcher.",topic:'off-topic'};}
function score(e,q,qt){let s=0,n=norm(q),exact=false;for(const p of e._patterns){if(n===p){s+=24;exact=true;}else if(n.length>=5&&(n.includes(p)||p.includes(n)))s+=Math.min(11,3+p.length/12);s+=overlap(qt,tokens(p))*4.4;}for(const t of qt){if(e._keywords.includes(t))s+=t.length>=7?3.2:2.2;else{let f=0;for(const k of e._keywords)f=Math.max(f,fuzzy(t,k));if(f>=.88)s+=1.25*f;}}if(state.lastTopic&&e.topic===state.lastTopic&&raw(q).length<=7)s+=2.2;return{score:s,exact};}
async function extended(q){const es=await load(),qt=tokens(q),rank=es.map(e=>{const x=score(e,q,qt);return{e,s:x.score,exact:x.exact}}).sort((a,b)=>b.s-a.s),b=rank[0],second=rank[1];if(!b)return null;const floor=qt.length<=1?8.8:qt.length===2?7.2:Math.min(10,4.8+qt.length*.72);const margin=second?b.s-second.s:b.s;if(b.s<floor)return null;if(!b.exact&&qt.length<=2&&margin<2.1)return null;return b;}
function remember(q,r){state.lastQuestion=q;if(r.topic)state.lastTopic=r.topic;state.entities={...state.entities,...entities(q)};state.history.push({q,topic:r.topic||''});if(state.history.length>6)state.history.shift();}
const related=t=>({installation:['How do I update safely?','What if signing expires?'],compatibility:['Best settings for 4 GB?','What causes thermal throttling?'],performance:['Should I use 30 or 40 FPS?','What does MetalFX do?'],graphics:['What resolution should I use?','Should I use MSAA?'],troubleshooting:['What if I get a black screen?','What if loading never finishes?'],characters:['Tell me about the three protagonists','Who is Lester?'],story:['How many endings are there?','What is the Big Score?'],heists:['What is the Big Score?','What is the Paleto Score?'],world:['Where is Mount Chiliad?','What is Sandy Shores?'],vehicles:['How do garages work?','Can I customize cars?'],multiplayer:['GTA Online vs Story Mode','Does GTA Online work on this iOS project?']}[t]||[]);
async function answer(q){const hello=greeting(q);if(hello){remember(q,hello);return hello;}const domain=domainDecision(q);if(!domain.allowed){const r=offTopic();remember(q,r);return r;}const en=context(q),hit=await extended(en);if(hit){const r={text:hit.e.answer,topic:hit.e.topic||'',source:hit.e.source||null,discord:hit.e.discord===true,suggestions:related(hit.e.topic)};remember(q,r);return r;}const e={...state.entities,...entities(q)},wants=/\b(settings?|preset|graphics|performance|fps|resolution)\b/.test(norm(q));if(wants&&(e.device||e.memory)){const lead=e.device?`Since we're talking about your ${e.device}${e.memory?' with '+e.memory+' of memory':''},`:`For that ${e.memory||'device'},`;const r={text:`${lead} start conservative: lower render resolution, keep MSAA off, use modest shadows, enable low-memory mode if your launcher build provides it, and prefer a stable FPS cap over an unstable higher target. Raise one setting at a time while watching heat and memory pressure.`,topic:'performance',source:{href:'compatibility.html',label:'Compatibility'},suggestions:related('performance')};remember(q,r);return r;}if(window.FranklinEngine?.answer){const r=await window.FranklinEngine.answer(en);if(r?.topic==='unknown'){const safe=offTopic();remember(q,safe);return safe;}remember(q,r||{});return r;}const safe=offTopic();remember(q,safe);return safe;}
